div.script:
$(document).ready(function()
                      {
                         setTimeout(
                                function()
                                {
                              var rowCount111 = $('#ttable1 td:visible').length;
                              var rowCount222 = $('#ttable2 td:visible').length;
                              var dummy111 =$('#ttable1 tr.dummy').length;
                              var dummy222 = $('#ttable2 tr.dummy').length;
                              if (rowCount111 > rowCount222)
                                  {
                                      var z1 = (rowCount111/2) - (rowCount222/2)
                                      if (dummy111 > 0)
                                      {
                                          if (z1 > dummy111)
                                          {
                                              for (let i = 0; i < z1; i++) {
                                                  $('#ttable2 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }
                                          }
                                          else
                                          {

                                              for (let i = 0; i < z1; i++) {

                                                $('#ttable1 tr.dummy:last').remove()
                                              }

                                          }
                                      }
                                      else
                                      {
                                          for (let i = 0; i < z1; i++) {
                                                  $('#ttable2 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }

                                      }
                                  }
                                  else{
                                      var z2 = (rowCount222/2) - (rowCount111/2)
                                      if (dummy222 > 0)
                                      {
                                          if (z2 > dummy222)
                                          {
                                              for (let i = 0; i < z2; i++) {
                                                  $('#ttable1 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
