                              setTimeout(
                                function()
                                {
                              var rowCount1 = $('#ttable1 td:visible').length;
                              var rowCount2 = $('#ttable2 td:visible').length;
                              var dummy1 =$('#ttable1 tr.dummy').length;
                              var dummy2 = $('#ttable2 tr.dummy').length;
                              if (rowCount1 > rowCount2)
                                  {
                                      var z = (rowCount1/2) - (rowCount2/2)
                                      if (dummy1 > 0)
                                      {
                                          if (z > dummy1)
                                          {
                                              for (let i = 0; i < z; i++) {
                                                  $('#ttable2 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }
                                          }
                                          else
