                                          for (let i = 0; i < z; i++) {
                                                  $('#ttable2 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }

                                      }
                                  }
                                  else{
                                      var z = (rowCount2/2) - (rowCount1/2)
                                      if (dummy2 > 0)
                                      {
                                          if (z > dummy2)
                                          {
                                              for (let i = 0; i < z; i++) {
                                                  $('#ttable1 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }
                                          }
                                          else
                                          {

                                              for (let i = 0; i < z; i++) {

                                                $('#ttable2 tr.dummy:last').remove()
