                                      {
                                          for (let i = 0; i < z; i++) {
                                                  $('#ttable1 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
