                              setTimeout(
                                function()
                                {
                                      var rowCount11 = $('#ttable1 td:visible').length;
                                      var rowCount22 = $('#ttable2 td:visible').length;
                                      var dummy11 =$('#ttable1 tr.dummy').length;
                                      var dummy22 = $('#ttable2 tr.dummy').length;

                                  if (rowCount11 > rowCount22)
                                  {
                                      var z = (rowCount11/2) - (rowCount22/2)
                                      if (dummy11 > 0)
                                      {
                                          if (z > dummy11)
                                          {
                                              for (let i = 0; i < z; i++) {
                                                  $('#ttable2 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }
                                          }
                                          else
                                          {

                                              for (let i = 0; i < z; i++) {

                                                $('#ttable1 tr.dummy:last').remove()
                                              }

                                          }
                                      }
                                      else
                                      {
                                          for (let i = 0; i < z; i++) {
                                                  $('#ttable2 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }

                                      }
                                  }
                                  else{
                                      var z = (rowCount22/2) - (rowCount11/2)
                                      if (dummy22 > 0)
                                      {
                                          if (z > dummy22)
                                          {
                                              for (let i = 0; i < z; i++) {
                                                  $('#ttable1 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }
                                          }
                                          else
                                          {

                                              for (let i = 0; i < z; i++) {

                                                $('#ttable2 tr.dummy:last').remove()
                                              }

                                          }
                                      }
                                      else
                                      {
                                          for (let i = 0; i < z; i++) {
                                                  $('#ttable1 tr:last').after('<tr class="dummy" style="border-bottom: 1px solid #ccc;"><td style="border-right:1px solid;"> </td><td style="border-right:1px solid;"> </td></tr>');
                                              }

                                      }
                                  }
                                }, 10);


                      }

                      });
                      });
